SET NOCOUNT ON; SELECT panel_code, panel_name, ISNULL(head_table,N'') AS head_table, ISNULL(line_table,N'') AS line_table, mode FROM dbo.yj_panel WHERE panel_code IN (N'QC_RECV',N'QC_INSP',N'QC_RETURN',N'PURCHASE_IN',N'QC_TC_IN',N'FINISH_IN',N'SALE_OUT',N'MATERIAL_OUT',N'MANU_ORDER',N'WO_REPORT',N'WO_REPORT_LIST',N'QC_MOLD_INSP',N'QC_CUT_INSP',N'QC_ASM_INSP',N'QC_PROC_INSP',N'QC_FIRST_INSP') ORDER BY panel_code;
